  register(name, skill) {
    this.skills.set(name, skill);
  }

  async execute(name, args) {
    const skill = this.skills.get(name);
    if (!skill) {
      throw new Error('技能 ' + name + ' 不存在');
    }
    return await skill.handler(args);
  }

  // === 技能实现 ===

  async _executeCode(args) {
    const { language, code } = args;
    try {
      let cmd;
      switch (language) {
        case 'python':
          cmd = 'python -c "' + code.replace(/"/g, '\"') + '"';
          break;
        case 'javascript':
        case 'js':
          cmd = 'node -e "' + code.replace(/"/g, '\"') + '"';
          break;
        case 'shell':
          cmd = code;
          break;
        default:
          throw new Error('不支持的语言: ' + language);
      }
      const result = execSync(cmd, { timeout: 30000, encoding: 'utf-8' });
